using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests.Quality;

public class QualityEvalTests
{
    private static readonly string ContentRoot =
        Path.Combine(AppContext.BaseDirectory, "Quality");

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = true
    };

    public static IEnumerable<object[]> GoldenCases()
    {
        var path = Path.Combine(ContentRoot, "golden.json");
        var json = File.ReadAllText(path);
        var cases = JsonSerializer.Deserialize<List<GoldenCase>>(json, JsonOptions)
            ?? throw new InvalidOperationException("golden.json returned null");

        foreach (var c in cases)
        {
            yield return new object[] { c.Id, c.UserMessage, c.ExpectedTraits };
        }
    }

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public async Task EvalCase_MeetsExpectedTraits(string id, string userMessage, string[] expectedTraits)
    {
        // Arrange: load the rubric for reference
        var rubricPath = Path.Combine(ContentRoot, "rubric.md");
        var rubric = await File.ReadAllTextAsync(rubricPath);

        // Act: invoke the agent under test
        // TODO: Replace with actual agent invocation via the AppHost
        var agentResponse = await InvokeAgentAsync(userMessage);

        // Assert: verify expected traits are present in the response
        Assert.NotNull(agentResponse);
        Assert.False(string.IsNullOrWhiteSpace(agentResponse),
            $"Case '{id}': Agent returned empty response for: {userMessage}");

        foreach (var trait in expectedTraits)
        {
            // Trait validation placeholder — replace with AI-based evaluation
            Assert.True(
                agentResponse.Contains(trait, StringComparison.OrdinalIgnoreCase),
                $"Case '{id}': Expected trait '{trait}' not found in response.");
        }
    }

    private static Task<string> InvokeAgentAsync(string userMessage)
    {
        // TODO: Wire up to the actual agentic app endpoint via Aspire AppHost
        // Example: use HttpClient against the AppHost's allocated endpoint
        return Task.FromResult(string.Empty);
    }
}

public record GoldenCase
{
    public string Id { get; init; } = string.Empty;
    public string UserMessage { get; init; } = string.Empty;
    public string[] ExpectedTraits { get; init; } = [];
}

